        if t == 0 and prev_on == 0 and on_t0 == 1 and p_t0 > SDR + 1e-6:
            errors.append(f"init-shutdown-ramp {g}")
    # min up / min down within horizon
    for t in range(T):
        if su[t] == 1:
            for k in range(t, min(T, t + TU)):
                if c[k] != 1:
                    errors.append(f"min-up {g} t{t}")
        if sd[t] == 1:
            for k in range(t, min(T, t + TD)):
                if c[k] != 0:
                    errors.append(f"min-down {g} t{t}")
    # startup tier lag legality (cheapest tier used)
    lag = min(s["lag"] for s in G["startup"])
    if lag > TD and any(su):
        # start after exactly min-down would need tier with lag <= down time; TD>=lag verified earlier
        pass
    if G["must_run"] and any(v != 1 for v in c):
        errors.append(f"must-run {g}")

for k in RN:
