report = {
    "case_name": "unit_commitment_schedule",
    "summary": {
        "solver_status": "optimal" if status == "Optimal" else status.lower(),
        "objective_cost": round(total_cost, 2),
        "reported_mip_gap": 0.0 if status == "Optimal" else None,
        "time_periods": T,
        "num_thermal_generators": len(GN),
        "num_renewable_generators": len(RN),
        "total_startups": total_startups,
        "total_shutdowns": total_shutdowns,
