        cap = min(head, ru)
        if res[g][t] > cap + 1e-9:
            res[g][t] = round(max(0.0, cap), ND)
    shortfall = RESERVES[t] - sum(res[g][t] for g in GN)
    if shortfall > 0:
        for g in GN:
