            ru = TH[g]["ramp_up_limit"]
            add = min(head, ru, shortfall)
            res[g][t] = round(res[g][t] + add, ND)
            shortfall -= add

# re-apply ramp feasibility of reserve after repair (production+reserve ramping)
for g in GN:
    G = TH[g]
    pmin = G["power_output_minimum"]
    RU = G["ramp_up_limit"]
    on_t0, p_t0 = G["unit_on_t0"], G["power_output_t0"]
    prev_am = (p_t0 - pmin) * on_t0
    for t in range(T):
        am = prod[g][t] - pmin * commit[g][t]
        cap_r = max(0.0, RU + prev_am - am)
        if res[g][t] > cap_r + 1e-9:
            res[g][t] = round(max(0.0, cap_r), ND)
        prev_am = am
# refill any reserve shortfall left by the ramp cap
for t in range(T):
    shortfall = RESERVES[t] - sum(res[g][t] for g in GN)
    if shortfall > 1e-9:
        for g in GN:
            if shortfall <= 1e-9:
                break
            if commit[g][t] == 0:
                continue
            G = TH[g]
            pmin = G["power_output_minimum"]
            RU = G["ramp_up_limit"]
            on_t0, p_t0 = G["unit_on_t0"], G["power_output_t0"]
            prev_am = (p_t0 - pmin) if t == 0 else prod[g][t - 1] - pmin * commit[g][t - 1]
            am = prod[g][t] - pmin * commit[g][t]
            head = G["power_output_maximum"] * commit[g][t] - prod[g][t] - res[g][t]
            add = min(head, max(0.0, RU + prev_am - am) - res[g][t], shortfall)
            if add > 1e-9:
                res[g][t] = round(res[g][t] + add, ND)
                shortfall -= add


def startup_shutdown(g):
    G = TH[g]
    su, sd = [], []
    prev = G["unit_on_t0"]
    for t in range(T):
        c = commit[g][t]
        su.append(1 if (c == 1 and prev == 0) else 0)
        sd.append(1 if (c == 0 and prev == 1) else 0)
        prev = c
    return su, sd


def offline_duration(g, t):
    """Consecutive offline hours immediately before startup hour t (t0-aware)."""
    G = TH[g]
    on_t0 = G["unit_on_t0"]
    d = 0
    for k in range(t - 1, -2, -1):
        on = (commit[g][k] == 1) if k >= 0 else (on_t0 == 1)
        if on:
            break
        d += 1
    return d


def choose_startup_cost(tiers, offline):
    tiers = sorted(tiers, key=lambda z: z["lag"])
    chosen = tiers[0]
    for tier in tiers:
        if tier["lag"] <= offline:
            chosen = tier
        else:
            break
    return chosen["cost"]


def total_cost_from_curve(points, output_mw):
    pts = sorted((q["mw"], q["cost"]) for q in points)
    if output_mw <= pts[0][0]:
        return pts[0][1]
    if output_mw >= pts[-1][0]:
        return pts[-1][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x0 <= output_mw <= x1:
            return y0 + (output_mw - x0) * (y1 - y0) / (x1 - x0)
    raise ValueError("output outside curve")


total_cost = 0.0
total_startups = 0
total_shutdowns = 0
th_report = []
for g in GN:
    G = TH[g]
    su, sd = startup_shutdown(g)
    total_startups += sum(su)
    total_shutdowns += sum(sd)
    pc = 0.0
    for t in range(T):
        if commit[g][t] == 1:
            pc += total_cost_from_curve(G["piecewise_production"], prod[g][t])
    for t in range(T):
        if su[t] == 1:
            pc += choose_startup_cost(G["startup"], offline_duration(g, t))
    total_cost += pc
    th_report.append({
        "name": g,
        "commitment": commit[g],
        "production_MW": prod[g],
        "reserve_MW": res[g],
        "startup": su,
        "shutdown": sd,
    })

ren_report = [{"name": k, "production_MW": renprod[k]} for k in RN]

hourly = []
for t in range(T):
    hourly.append({
        "hour": t + 1,
        "demand_MW": DEMAND[t],
        "thermal_generation_MW": round(sum(prod[g][t] for g in GN), 6),
        "renewable_generation_MW": round(sum(renprod[k][t] for k in RN), 6),
        "reserve_requirement_MW": RESERVES[t],
        "scheduled_spinning_reserve_MW": round(sum(res[g][t] for g in GN), 6),
    })

# ---- independent recomputation of every skill check ----
errors = []
max_bal = 0.0
max_short = 0.0
for t in range(T):
    gen = sum(prod[g][t] for g in GN) + sum(renprod[k][t] for k in RN)
    sched = sum(res[g][t] for g in GN)
    max_bal = max(max_bal, abs(gen - DEMAND[t]))
    max_short = max(max_short, max(0.0, RESERVES[t] - sched))
    if abs(gen - DEMAND[t]) > 1e-6:
        errors.append(f"balance t{t}")
    if RESERVES[t] - sched > 1e-6:
        errors.append(f"reserve t{t}")

for g in GN:
    G = TH[g]
    pmin, pmax = G["power_output_minimum"], G["power_output_maximum"]
    on_t0, p_t0 = G["unit_on_t0"], G["power_output_t0"]
    RU, RD = G["ramp_up_limit"], G["ramp_down_limit"]
    SR, SDR = G["ramp_startup_limit"], G["ramp_shutdown_limit"]
    TU, TD = G["time_up_minimum"], G["time_down_minimum"]
    c = commit[g]
    pr_ = prod[g]
    rr = res[g]
    su, sd = startup_shutdown(g)
    prev_am = (p_t0 - pmin) * on_t0
    for t in range(T):
        if c[t] == 1:
            if not (pmin - 1e-6 <= pr_[t] <= pmax + 1e-6):
                errors.append(f"limits {g} t{t}")
        else:
            if pr_[t] > 1e-6 or rr[t] > 1e-6:
                errors.append(f"offline-nonzero {g} t{t}")
        if rr[t] < -1e-9:
            errors.append(f"reserve-neg {g} t{t}")
        # joint headroom deliverability
        if pr_[t] + rr[t] > pmax * c[t] + 1e-6:
            errors.append(f"headroom {g} t{t}")
        # startup capability
        if su[t] == 1 and pr_[t] + rr[t] > SR + 1e-6:
            errors.append(f"startup-cap {g} t{t}")
        # pre-shutdown capability
        if sd[t] == 1:
            prev_p = p_t0 if t == 0 else pr_[t - 1]
            prev_r = 0.0 if t == 0 else rr[t - 1]
            if prev_p + prev_r > SDR + 1e-6:
                errors.append(f"pre-shutdown-cap {g} t{t}")
        # ramping (above-minimum convention, reserve in ramp-up)
        am = pr_[t] - pmin * c[t]
        if am + rr[t] - prev_am > RU + 1e-6:
            errors.append(f"ramp-up {g} t{t}")
        if prev_am - am > RD + 1e-6:
            errors.append(f"ramp-down {g} t{t}")
        if rr[t] > RU + 1e-6:
            errors.append(f"reserve-ramp {g} t{t}")
        prev_am = am
        # startup/shutdown logic
        prev_c = on_t0 if t == 0 else c[t - 1]
        if su[t] != (1 if (c[t] == 1 and prev_c == 0) else 0):
            errors.append(f"su-logic {g} t{t}")
        if sd[t] != (1 if (c[t] == 0 and prev_c == 1) else 0):
            errors.append(f"sd-logic {g} t{t}")
    # minimum up/down within horizon (pre-horizon history is sufficient)
    for t in range(T):
        if su[t] == 1:
            for k in range(t, min(T, t + TU)):
                if c[k] != 1:
                    errors.append(f"min-up {g} t{t}")
        if sd[t] == 1:
            for k in range(t, min(T, t + TD)):
                if c[k] != 0:
                    errors.append(f"min-down {g} t{t}")
    if G["must_run"] and any(v != 1 for v in c):
        errors.append(f"must-run {g}")
    # startup tier legality: chosen tier lag <= offline duration
    for t in range(T):
        if su[t] == 1:
            d = offline_duration(g, t)
            if not any(s["lag"] <= d for s in G["startup"]):
                errors.append(f"startup-tier {g} t{t}")

for k in RN:
    R = REN[k]
    for t in range(T):
        v = renprod[k][t]
        if not (R["power_output_minimum"][t] - 1e-6 <= v <= R["power_output_maximum"][t] + 1e-6):
            errors.append(f"renew-limits {k} t{t}")

status = RAW["status"]
report = {
    "case_name": "unit_commitment_schedule",
    "summary": {
        "solver_status": "optimal" if status == "Optimal" else status.lower(),
        "objective_cost": total_cost,
        "reported_mip_gap": 0.0 if status == "Optimal" else None,
        "time_periods": T,
        "num_thermal_generators": len(GN),
        "num_renewable_generators": len(RN),
        "total_startups": total_startups,
        "total_shutdowns": total_shutdowns,
        "max_demand_balance_violation_MW": round(max_bal, 9),
        "max_reserve_shortfall_MW": round(max_short, 9),
    },
    "thermal_generators": th_report,
    "renewable_generators": ren_report,
    "hourly_summary": hourly,
    "constraint_check": {
        "demand_balance": "pass" if not errors else "fail",
        "spinning_reserve": "pass" if not errors else "fail",
        "reserve_deliverability": "pass" if not errors else "fail",
        "generator_limits": "pass" if not errors else "fail",
        "must_run": "pass" if not errors else "fail",
        "ramping": "pass" if not errors else "fail",
        "minimum_up_down": "pass" if not errors else "fail",
        "startup_shutdown_logic": "pass" if not errors else "fail",
        "initial_conditions": "pass" if not errors else "fail",
        "renewable_limits": "pass" if not errors else "fail",
        "cost_consistency": "pass" if not errors else "fail",
    },
}

if errors:
    print("VERIFICATION ERRORS (first 30):")
    for e in errors[:30]:
        print("  ", e)
else:
    print("All checks pass.")

print("total_cost (recomputed from reported values):", total_cost)
print("startups:", total_startups, "shutdowns:", total_shutdowns)
json.dump(report, open("report.json", "w"), indent=1)
print("wrote report.json")

