"""Build report.json from solution_raw.json with rounding repair and full re-verification."""
import json

DATA = json.load(open("network.json"))
T = DATA["time_periods"]
DEMAND = DATA["demand"]
RESERVES = DATA["reserves"]
TH = DATA["thermal_generators"]
REN = DATA["renewable_generators"]
GN = list(TH.keys())
RN = list(REN.keys())

RAW = json.load(open("solution_raw.json"))
commit = RAW["commit"]
prod = RAW["prod"]
res = RAW["res"]
renprod = RAW["renprod"]

ND = 6  # decimals

# ---- rounding + repair so that reported numbers are exactly consistent ----
prod = {g: [round(v, ND) for v in prod[g]] for g in GN}
res = {g: [round(v, ND) for v in res[g]] for g in GN}
renprod = {k: [round(v, ND) for v in renprod[k]] for k in RN}

for t in range(T):
    # demand balance residual
    resid = DEMAND[t] - sum(prod[g][t] for g in GN) - sum(renprod[k][t] for k in RN)
    if abs(resid) > 0:
        # pick thermal unit with most slack in the needed direction
        best, best_slack = None, -1e18
        for g in GN:
            if commit[g][t] == 0:
                continue
            head = TH[g]["power_output_maximum"] * commit[g][t] - prod[g][t] - res[g][t]
            room = prod[g][t] - TH[g]["power_output_minimum"]
            slack = head if resid > 0 else room
            if slack > best_slack:
                best_slack, best = slack, g
        prod[best][t] = round(prod[best][t] + resid, ND)
    # reserve shortfall / per-unit headroom fixes
    shortfall = RESERVES[t] - sum(res[g][t] for g in GN)
    for g in GN:
        head = TH[g]["power_output_maximum"] * commit[g][t] - prod[g][t]
        if res[g][t] > head + 1e-9:
            res[g][t] = round(max(0.0, head), ND)
    shortfall = RESERVES[t] - sum(res[g][t] for g in GN)
    if shortfall > 0:
        # distribute shortfall over units with headroom
        for g in GN:
            if shortfall <= 0:
                break
            if commit[g][t] == 0:
                continue
            head = TH[g]["power_output_maximum"] * commit[g][t] - prod[g][t] - res[g][t]
            add = min(head, shortfall)
            res[g][t] = round(res[g][t] + add, ND)
            shortfall -= add

# commitment-derived startup/shutdown events (guarantees logic consistency)
def startup_shutdown(g):
    G = TH[g]
    su, sd = [], []
    prev = G["unit_on_t0"]
    for t in range(T):
        c = commit[g][t]
        su.append(1 if (c == 1 and prev == 0) else 0)
        sd.append(1 if (c == 0 and prev == 1) else 0)
        prev = c
    return su, sd

# ---- cost recomputation from reported values ----
def prod_cost(g, pval):
    pw = TH[g]["piecewise_production"]
    mws = [pt["mw"] for pt in pw]
    cs = [pt["cost"] for pt in pw]
    if pval <= mws[0] + 1e-12:
        return cs[0]
    cost = cs[0]
    for i in range(len(mws) - 1):
        if pval >= mws[i + 1] - 1e-12:
            cost += cs[i + 1] - cs[i]
        else:
            cost += (cs[i + 1] - cs[i]) / (mws[i + 1] - mws[i]) * (pval - mws[i])
            break
    return cost

total_cost = 0.0
total_startups = 0
total_shutdowns = 0
th_report = []
for g in GN:
    su, sd = startup_shutdown(g)
    total_startups += sum(su)
    total_shutdowns += sum(sd)
    pc = 0.0
    for t in range(T):
        if commit[g][t] == 1:
            pc += prod_cost(g, prod[g][t])
        for s in TH[g]["startup"]:
            if s["cost"] == min(x["cost"] for x in TH[g]["startup"]):
                cstart = s["cost"]
    pc += cstart * sum(su)
    total_cost += pc
    th_report.append(
        {
            "name": g,
            "commitment": commit[g],
            "production_MW": prod[g],
            "reserve_MW": res[g],
            "startup": su,
            "shutdown": sd,
        }
    )

ren_report = [{"name": k, "production_MW": renprod[k]} for k in RN]

hourly = []
for t in range(T):
    hourly.append(
        {
            "hour": t + 1,
            "demand_MW": DEMAND[t],
            "thermal_generation_MW": round(sum(prod[g][t] for g in GN), 6),
            "renewable_generation_MW": round(sum(renprod[k][t] for k in RN), 6),
            "reserve_requirement_MW": RESERVES[t],
            "scheduled_spinning_reserve_MW": round(sum(res[g][t] for g in GN), 6),
        }
    )

# ---- independent recomputation of every check ----
errors = []
max_bal = 0.0
max_short = 0.0
for t in range(T):
    gen = sum(prod[g][t] for g in GN) + sum(renprod[k][t] for k in RN)
    max_bal = max(max_bal, abs(gen - DEMAND[t]))
    sched = sum(res[g][t] for g in GN)
    max_short = max(max_short, max(0.0, RESERVES[t] - sched))
    if abs(gen - DEMAND[t]) > 1e-6:
        errors.append(f"balance t{t}")
    if RESERVES[t] - sched > 1e-6:
        errors.append(f"reserve t{t}")

for g in GN:
    G = TH[g]
    pmin, pmax = G["power_output_minimum"], G["power_output_maximum"]
    on_t0, p_t0 = G["unit_on_t0"], G["power_output_t0"]
    RU, RD = G["ramp_up_limit"], G["ramp_down_limit"]
    SR, SDR = G["ramp_startup_limit"], G["ramp_shutdown_limit"]
    TU, TD = G["time_up_minimum"], G["time_down_minimum"]
    c = commit[g]
    pr_ = prod[g]
    rr = res[g]
    su, sd = startup_shutdown(g)
    for t in range(T):
        if c[t] == 1 and not (pmin - 1e-6 <= pr_[t] <= pmax + 1e-6):
            errors.append(f"limits {g} t{t}")
        if c[t] == 0 and pr_[t] > 1e-6:
            errors.append(f"limits-off {g} t{t}")
        if rr[t] > pmax * c[t] - pr_[t] + 1e-6:
            errors.append(f"reserve-headroom {g} t{t}")
        if rr[t] < -1e-9:
            errors.append(f"reserve-neg {g} t{t}")
        # startup/shutdown logic vs commitment
        prev_c = on_t0 if t == 0 else c[t - 1]
        if su[t] != (1 if (c[t] == 1 and prev_c == 0) else 0):
            errors.append(f"su-logic {g} t{t}")
        if sd[t] != (1 if (c[t] == 0 and prev_c == 1) else 0):
            errors.append(f"sd-logic {g} t{t}")
        if su[t] and sd[t]:
            errors.append(f"su&sd {g} t{t}")
        # ramping
        prev_p = p_t0 if t == 0 else pr_[t - 1]
        prev_on = on_t0 if t == 0 else c[t - 1]
        if c[t] == 1 and prev_on == 1:
            if pr_[t] - prev_p > RU + 1e-6:
                errors.append(f"ramp-up {g} t{t}")
            if prev_p - pr_[t] > RD + 1e-6:
                errors.append(f"ramp-down {g} t{t}")
        if su[t] == 1 and pr_[t] > SR + 1e-6:
            errors.append(f"startup-ramp {g} t{t}")
        if sd[t] == 1 and prev_p > SDR + 1e-6:
            errors.append(f"shutdown-ramp {g} t{t}")
        # initial conditions
