"""Build report.json from solution_raw.json (v2).

Startup cost uses the tier rule from the operating-rules skill: chosen tier is
the largest lag not exceeding the prior offline duration. Production cost uses
total-cost breakpoint interpolation. All constraint checks are recomputed
independently from the reported arrays before writing "pass".
"""
import json

DATA = json.load(open("network.json"))
T = DATA["time_periods"]
DEMAND = DATA["demand"]
RESERVES = DATA["reserves"]
TH = DATA["thermal_generators"]
REN = DATA["renewable_generators"]
GN = list(TH.keys())
RN = list(REN.keys())

RAW = json.load(open("solution_raw.json"))
commit = RAW["commit"]
prod = {g: [round(v, 6) for v in RAW["prod"][g]] for g in GN}
res = {g: [round(v, 6) for v in RAW["res"][g]] for g in GN}
renprod = {k: [round(v, 6) for v in RAW["renprod"][k]] for k in RN}

ND = 6
BIG = 1e9

# ---- rounding repair so reported numbers are exactly consistent ----
for t in range(T):
    resid = DEMAND[t] - sum(prod[g][t] for g in GN) - sum(renprod[k][t] for k in RN)
    if abs(resid) > 0:
        best, best_slack = None, -1e18
        for g in GN:
            if commit[g][t] == 0:
                continue
            head = TH[g]["power_output_maximum"] * commit[g][t] - prod[g][t] - res[g][t]
            room = prod[g][t] - TH[g]["power_output_minimum"]
            slack = head if resid > 0 else room
            if slack > best_slack:
                best_slack, best = slack, g
        prod[best][t] = round(prod[best][t] + resid, ND)
    for g in GN:
        head = TH[g]["power_output_maximum"] * commit[g][t] - prod[g][t]
        ru = TH[g]["ramp_up_limit"]
        cap = min(head, ru)
        if res[g][t] > cap + 1e-9:
            res[g][t] = round(max(0.0, cap), ND)
    shortfall = RESERVES[t] - sum(res[g][t] for g in GN)
    if shortfall > 0:
        for g in GN:
            if shortfall <= 0:
                break
            if commit[g][t] == 0:
                continue
            head = TH[g]["power_output_maximum"] * commit[g][t] - prod[g][t] - res[g][t]
            ru = TH[g]["ramp_up_limit"]
            add = min(head, ru, shortfall)
            res[g][t] = round(res[g][t] + add, ND)
            shortfall -= add

# re-apply ramp feasibility of reserve after repair (production+reserve ramping)
for g in GN:
    G = TH[g]
    pmin = G["power_output_minimum"]
    RU = G["ramp_up_limit"]
    on_t0, p_t0 = G["unit_on_t0"], G["power_output_t0"]
    prev_am = (p_t0 - pmin) * on_t0
    for t in range(T):
        am = prod[g][t] - pmin * commit[g][t]
        cap_r = max(0.0, RU + prev_am - am)
        if res[g][t] > cap_r + 1e-9:
            res[g][t] = round(max(0.0, cap_r), ND)
        prev_am = am
# refill any reserve shortfall left by the ramp cap
for t in range(T):
    shortfall = RESERVES[t] - sum(res[g][t] for g in GN)
    if shortfall > 1e-9:
        for g in GN:
            if shortfall <= 1e-9:
                break
            if commit[g][t] == 0:
                continue
            G = TH[g]
            pmin = G["power_output_minimum"]
            RU = G["ramp_up_limit"]
            on_t0, p_t0 = G["unit_on_t0"], G["power_output_t0"]
            prev_am = (p_t0 - pmin) if t == 0 else prod[g][t - 1] - pmin * commit[g][t - 1]
            am = prod[g][t] - pmin * commit[g][t]
            head = G["power_output_maximum"] * commit[g][t] - prod[g][t] - res[g][t]
            add = min(head, max(0.0, RU + prev_am - am) - res[g][t], shortfall)
            if add > 1e-9:
                res[g][t] = round(res[g][t] + add, ND)
                shortfall -= add


def startup_shutdown(g):
    G = TH[g]
    su, sd = [], []
    prev = G["unit_on_t0"]
    for t in range(T):
        c = commit[g][t]
        su.append(1 if (c == 1 and prev == 0) else 0)
        sd.append(1 if (c == 0 and prev == 1) else 0)
        prev = c
    return su, sd


def offline_duration(g, t):
    """Consecutive offline hours immediately before startup hour t (t0-aware)."""
    G = TH[g]
    on_t0 = G["unit_on_t0"]
    d = 0
    for k in range(t - 1, -2, -1):
        on = (commit[g][k] == 1) if k >= 0 else (on_t0 == 1)
        if on:
            break
        d += 1
    return d


def choose_startup_cost(tiers, offline):
    tiers = sorted(tiers, key=lambda z: z["lag"])
    chosen = tiers[0]
    for tier in tiers:
        if tier["lag"] <= offline:
            chosen = tier
        else:
            break
    return chosen["cost"]


def total_cost_from_curve(points, output_mw):
    pts = sorted((q["mw"], q["cost"]) for q in points)
    if output_mw <= pts[0][0]:
        return pts[0][1]
    if output_mw >= pts[-1][0]:
        return pts[-1][1]
    for (x0, y0), (x1, y1) in zip(pts, pts[1:]):
        if x0 <= output_mw <= x1:
            return y0 + (output_mw - x0) * (y1 - y0) / (x1 - x0)
    raise ValueError("output outside curve")


total_cost = 0.0
total_startups = 0
total_shutdowns = 0
th_report = []
for g in GN:
    G = TH[g]
    su, sd = startup_shutdown(g)
    total_startups += sum(su)
    total_shutdowns += sum(sd)
    pc = 0.0
    for t in range(T):
        if commit[g][t] == 1:
            pc += total_cost_from_curve(G["piecewise_production"], prod[g][t])
    for t in range(T):
        if su[t] == 1:
            pc += choose_startup_cost(G["startup"], offline_duration(g, t))
    total_cost += pc
    th_report.append({
